export const ES_THEMES: ContentCatalogue = {
  "themes.angels.absence.0": { fp: "1wxkim", text: "Lo que aquí se lee de 1 Enoc es la traducción de una traducción. El Libro de los Vigilantes se escribió en arameo, los autores del Nuevo Testamento lo leyeron en griego, y solo se conserva completo en ge'ez —etiópico—, de donde R. H. Charles sacó el inglés que aparece abajo. Del arameo hay fragmentos de Qumrán y del griego una parte. Cuando una expresión importa, conviene recordar cuánto camino ha recorrido." },
  "themes.angels.absence.1": { fp: "3gietq", text: "Falta la liturgia angélica. Los Cantos del Sacrificio Sabático, de Qumrán, son el único texto que muestra qué se imaginaba que la corte celestial estaba HACIENDO —ángeles sacerdotes sirviendo en un santuario celestial, semana tras semana— y no existe ninguna versión inglesa de los rollos en dominio público ni con licencia abierta. Todo lo que aparece abajo ve a los ángeles desde la tierra, mirando hacia arriba." },
  "themes.angels.anchors": { fp: "1wommmm", text: "Las anclas son Génesis 6:1–4, Deuteronomio 32:8 (en el griego, «según el número de los ángeles de Dios»), Daniel 10 y 12:1, e Isaías 6. Son canónicos y quedan fuera de este corpus; 1 Enoc amplía el primero, Jubileos el segundo, y Daniel es el único lugar de la Escritura donde Miguel y Gabriel reciben sus nombres." },
  "themes.angels.blurb": { fp: "m62pzq", text: "Aquí los ángeles reciben nombres, rangos, oficios y una historia que la Biblia hebrea nunca les da, y las fuentes no se avergüenzan de decir de dónde salió todo eso: un rabino del Yerushalmí afirma sin rodeos que los nombres subieron de Babilonia con los desterrados. 1 Enoc aporta el relato al que todos los demás reaccionan: doscientos de ellos bajan, se casan, enseñan metalurgia, cosmética y astrología, y sus hijos muertos se vuelven los demonios. Jubileos ordena a los ángeles por departamentos el primer día de la creación y pone uno sobre cada nación menos Israel. Y en Orígenes un crítico pagano ya hace la pregunta incómoda: si ustedes honran a esos seres, ¿cuántos dioses tienen?" },
  "themes.angels.label": { fp: "1ak8i7s", text: "Los ángeles y la corte celestial" },
  "themes.angels.sum.1enoch.15.8": { fp: "gdpig9", text: "Los gigantes muertos son los espíritus malignos de aquí" },
  "themes.angels.sum.1enoch.20.1": { fp: "1si1gso", text: "Una lista: los nombres de los ángeles vigilantes" },
  "themes.angels.sum.1enoch.6.2": { fp: "ilx523", text: "Los ángeles ven a las hijas de los hombres y bajan" },
  "themes.angels.sum.1enoch.8.1": { fp: "99r4ld", text: "Azazel enseñó armas, metales, joyas, pintura de ojos" },
  "themes.angels.sum.1enoch.9.1": { fp: "362zwo", text: "Cuatro arcángeles miran abajo y ven el derramamiento de sangre" },
  "themes.angels.sum.Tob.5.4": { fp: "f71pzv", text: "Rafael contratado como compañero de viaje, sin ser reconocido" },
  "themes.angels.sum.af-hermas.69.3": { fp: "x2glb9", text: "Miguel pone la ley en el corazón de los creyentes" },
  "themes.angels.sum.af-ign-trallians.5.2": { fp: "918e2h", text: "Conoce los rangos y no se atribuye ninguno" },
  "themes.angels.sum.athanasius-arians-3.14.1": { fp: "4zmgle", text: "Cuando obra el Padre, ningún ángel obra" },
  "themes.angels.sum.hesiod-works-and-days.2.250": { fp: "ngrbqe", text: "Treinta mil espíritus vigilan los juicios torcidos de los mortales" },
  "themes.angels.sum.jubilees.15.31": { fp: "qdu7sc", text: "Espíritus puestos sobre las naciones, para extraviarlas" },
  "themes.angels.sum.jubilees.15.32": { fp: "jtroce", text: "Sobre Israel ningún ángel: Dios gobierna directamente" },
  "themes.angels.sum.jubilees.2.2": { fp: "1ic4qap", text: "Creados el día uno: ángeles de fuego, viento, nube" },
  "themes.angels.sum.origen-celsus-8.13.1": { fp: "1ppts81", text: "Si se puede adorar a Gabriel y a Miguel" },
  "themes.angels.sum.testament-of-abraham-a.10.1": { fp: "smv152", text: "Miguel lleva a Abraham en un carro de querubines" },
  "themes.angels.sum.tg-psj-exodus.24.1": { fp: "1legfz9", text: "Miguel, Príncipe de la Sabiduría, habla por Dios" },
  "themes.angels.sum.tg-psj-genesis.32.25": { fp: "lmgum2", text: "El luchador discute por un diezmo no pagado" },
  "themes.angels.sum.y-rosh-hashanah.1.2": { fp: "m0k0hp", text: "Los nombres de los ángeles subieron de Babilonia" },
  "themes.atonement.absence.0": { fp: "1dxks69", text: "El macho cabrío emisario se describe una y otra vez y no se explica en ninguna parte. Ni una sola fuente de aquí dice CÓMO llega el pecado al animal, ni por qué enviarlo lejos quita algo. El mecanismo que un lector moderno quiere sencillamente no es una pregunta que estos autores se hagan." },
  "themes.atonement.absence.1": { fp: "q5ey5g", text: "La muerte expiatoria vicaria sí está aquí, pero pertenece a los MÁRTIRES, no a un mesías. 4 Macabeos dice que la sangre de los piadosos salvó a Israel; ninguna fuente judía de esta biblioteca dice nada semejante de un rey ungido. Esa distinción es todo el asunto, y la página [[Messiah]] hace la misma desde el otro lado." },
  "themes.atonement.anchors": { fp: "c8rd4z", text: "Las anclas son Levítico 16 (el Día de la Expiación y los dos machos cabríos), Levítico 17:11 («la vida de la carne está en la sangre») e Isaías 53. Son canónicos y quedan fuera de este corpus; todos los textos de abajo trabajan a partir de ellos." },
  "themes.atonement.blurb": { fp: "loyhks", text: "Cómo se resuelve el pecado. La respuesta ritual es el Día de la Expiación, descrito aquí por Filón, Josefo, los Targumim y los rabinos. La otra respuesta es la que un lector del Nuevo Testamento no espera encontrar en fuentes judías: en 4 Macabeos las muertes de los mártires son purificación y propiciación por la nación." },
  "themes.atonement.label": { fp: "1h865lw", text: "La expiación y el sacrificio" },
  "themes.atonement.sum.2Macc.7.38": { fp: "1jq73wk", text: "Cese en nosotros la ira del Todopoderoso" },
  "themes.atonement.sum.4Macc.17.22": { fp: "zb0p76", text: "La muerte propiciatoria de los mártires salvó a Israel" },
  "themes.atonement.sum.4Macc.6.29": { fp: "16pdvsn", text: "Sea mi sangre su purificación, y mi vida el rescate" },
  "themes.atonement.sum.Sir.7.31": { fp: "1tyw06o", text: "Honra al sacerdote; da la ofrenda por la culpa" },
  "themes.atonement.sum.af-1clement.7.4": { fp: "1179q8a", text: "La sangre de Cristo, derramada por nuestra salvación" },
  "themes.atonement.sum.af-barnabas.2.5": { fp: "1twr37r", text: "Dios declara que está harto de holocaustos" },
  "themes.atonement.sum.af-barnabas.7.6": { fp: "1gzrt8o", text: "Dos machos cabríos, iguales y parejos, leídos tipológicamente" },
  "themes.atonement.sum.antiquities.10.241": { fp: "fiawvz", text: "El macho cabrío emisario, expiación por toda la multitud" },
  "themes.atonement.sum.herodotus-histories-7.197.3": { fp: "asrie", text: "Un hombre hecho chivo expiatorio del país, y sacrificado" },
  "themes.atonement.sum.m-shevuot.1.3": { fp: "8z16b2", text: "El macho cabrío y el Día de la Expiación expían juntos" },
  "themes.atonement.sum.philo-planter.1.61": { fp: "1g2r6ow", text: "Dos machos cabríos echados a suertes cada año" },
  "themes.atonement.sum.tg-psj-exodus.30.10": { fp: "aw5okl", text: "Aarón expía los cuernos del altar una vez al año" },
  "themes.atonement.sum.y-shevuot.1.7": { fp: "1ywbdrg", text: "La sangre del novillo expía solo por los sacerdotes" },
  "themes.character-of-god.absence.0": { fp: "27m8f9", text: "Nadie aquí resuelve la tensión, y la página está dispuesta de manera que se los pueda ver negándose a resolverla. Éxodo 34 promete perdón y se niega a absolver en un mismo aliento, y las fuentes reproducen eso en lugar de elegir: 4 Esdras afirma ambas cosas con un capítulo de distancia, el Sirácida pone la misericordia y la ira lado a lado como venidas del mismo Dios, y la Oración de Manasés simplemente apela a la primera mitad. La pregunta sistemática —cómo puede un Dios ser las dos cosas— se plantea aquí y no se responde en ninguna parte." },
  "themes.character-of-god.absence.1": { fp: "1i074lk", text: "El mundo griego y romano falta en esta página, y su ausencia es justamente lo que importa. La teología filosófica de ese mundo discutía si Dios puede sentir algo en absoluto, y un Dios que es provocado, que se vuelve atrás y que se describe con una lista de disposiciones morales no tenía lugar allí. No hay en esta biblioteca ningún texto pagano que pudiera ponerse debajo de estos; lo más cercano es la identificación estoica de Dios con la razón, que está en la página [[Godhead]]." },
  "themes.character-of-god.anchors": { fp: "urr03n", text: "El ancla es Éxodo 34:6–7, los trece atributos, proclamados mientras el SEÑOR pasa delante de Moisés. Se cita o se evoca por todo el canon —Números 14:18, Joel 2:13, Jonás 4:2, Salmo 86:15, Nehemías 9:17— y el Targum que aparece abajo lo está traduciendo directamente. Es canónico y queda fuera de este corpus; todo lo que hay aquí trabaja a partir de él." },
  "themes.character-of-god.blurb": { fp: "8acgrr", text: "Éxodo 34:6–7 es la frase que el resto de la Biblia no deja de citar —misericordioso, clemente, lento para la ira, que perdona la iniquidad y que de ningún modo tiene por inocente al culpable— y las fuentes reunidas aquí no la suavizan. 4 Esdras toma los atributos uno por uno y da una razón para cada uno, y luego dice que en el día del juicio la compasión pasará y la longanimidad será retirada: las dos cosas, en un mismo libro. El Sirácida convierte la fórmula en una advertencia, porque el que sabe que Dios es paciente puede decidir aprovecharse de eso. Filón llama a Dios misericordioso y clemente en la misma frase en la que lo hace destruir a un rey. Y en la Misná las palabras se han endurecido hasta volverse un NOMBRE: se puede jurar por el Clemente y Misericordioso, como se juraría por el Todopoderoso." },
  "themes.character-of-god.label": { fp: "1x900hm", text: "El carácter de Dios" },
  "themes.character-of-god.sum.2baruch.75.5": { fp: "f0nmlq", text: "¿Quién podría esperar, si no fuera por la misericordia y la gracia?" },
  "themes.character-of-god.sum.2esdras.7.132": { fp: "yon7ok", text: "Misericordioso: con los que todavía no han nacido" },
  "themes.character-of-god.sum.2esdras.7.134": { fp: "zqw8sa", text: "Longánime: soporta a sus propias criaturas" },
  "themes.character-of-god.sum.2esdras.7.138": { fp: "1vf1de", text: "Que perdona: o apenas quedaría alguien" },
  "themes.character-of-god.sum.2esdras.7.139": { fp: "1c1v9l8", text: "Y juez: en la misma lista" },
  "themes.character-of-god.sum.2esdras.7.33": { fp: "hywkj2", text: "En el juicio, la compasión desaparece" },
  "themes.character-of-god.sum.Odes.12.7": { fp: "z5xzxl", text: "Gran compasión, longanimidad, que se arrepiente de los males" },
  "themes.character-of-god.sum.Sir.2.11": { fp: "9a8ckg", text: "Lleno de compasión, longánime, que perdona los pecados" },
  "themes.character-of-god.sum.Sir.5.4": { fp: "1rqad1e", text: "No digas: es paciente, no pasó nada" },
  "themes.character-of-god.sum.Sir.5.6": { fp: "47hnir", text: "La misericordia y la ira vienen las dos de él" },
  "themes.character-of-god.sum.af-1clement.23.1": { fp: "1nby5i3", text: "Compasivo en todo, presto a hacer el bien" },
  "themes.character-of-god.sum.af-1clement.60.1": { fp: "1q7pucq", text: "Fiel por todas las generaciones, justo en el juicio" },
  "themes.character-of-god.sum.m-shevuot.4.13": { fp: "1ek2ail", text: "Jurar «por el Clemente y Misericordioso»" },
  "themes.character-of-god.sum.philo-abraham.1.96": { fp: "h7vqku", text: "El Dios misericordioso, que castiga en un instante" },
  "themes.character-of-god.sum.tg-psj-exodus.34.6": { fp: "1czky0l", text: "La Shekiná pasa: misericordioso, clemente, longánime" },
  "themes.character-of-god.sum.y-shevuot.4.10": { fp: "17e5dm3", text: "El mismo juramento, discutido en el Yerushalmí" },
  "themes.free-will.absence.0": { fp: "18b2959", text: "El determinismo de Qumrán —los dos espíritus, la suerte de la luz y la suerte de las tinieblas— es la postura judía más aguda sobre esta cuestión y está ausente, porque esta biblioteca no tiene ningún Rollo del Mar Muerto. Josefo dice que los esenios lo atribuían todo al destino; no podemos leerlos diciéndolo ellos mismos." },
  "themes.free-will.absence.1": { fp: "1wpnq4z", text: "Ninguna fuente de aquí separa la cuestión de la responsabilidad. Nadie sostiene que el destino excuse a nadie; incluso el relato más determinista que reporta Josefo se ofrece como postura de un partido, no como defensa." },
  "themes.free-will.anchors": { fp: "srn7u9", text: "Las anclas son Deuteronomio 30:19 («he puesto delante de ti la vida y la muerte: escoge la vida») y Génesis 4:7. Son canónicos y quedan fuera de este corpus; el Sirácida, en particular, escribe directamente a partir de ellos." },
  "themes.free-will.blurb": { fp: "1k6wwil", text: "Cuánto es destino y cuánto es elección. Josefo clasifica a los tres partidos judíos justamente por esta pregunta —es el mismo pasaje que los divide en cuanto a la resurrección— y el Sirácida y 2 Baruc la responden con tanta franqueza como cualquier texto antiguo: al hombre se lo deja en manos de su propio albedrío, y cada uno de nosotros es el Adán de su propia alma. Conviene leerlos junto a Epicteto, que no discute con ellos y llega a la formulación más aguda de todas: nada en absoluto es nuestro salvo el uso que hacemos de lo que sucede. Orígenes, al escribir el primer tratado cristiano sobre la cuestión, llega casi a la misma distinción por otro camino." },
  "themes.free-will.label": { fp: "1bedt65", text: "El libre albedrío y la providencia" },
  "themes.free-will.sum.2baruch.54.15": { fp: "6b395b", text: "Adán pecó primero, pero cada uno prepara lo suyo" },
  "themes.free-will.sum.2baruch.54.19": { fp: "xf77m5", text: "Cada uno de nosotros es el Adán de su alma" },
  "themes.free-will.sum.Sir.15.14": { fp: "1qaxfe3", text: "Dios dejó al hombre en manos de su albedrío" },
  "themes.free-will.sum.Sir.15.16": { fp: "1xrncx6", text: "Fuego y agua puestos delante de ti: escoge" },
  "themes.free-will.sum.af-didache.1.1": { fp: "1rtkghv", text: "Dos caminos, uno de vida y otro de muerte" },
  "themes.free-will.sum.af-didache.5.1": { fp: "15jt7cu", text: "El camino de la muerte expuesto por completo" },
  "themes.free-will.sum.antiquities.5.171": { fp: "19acwvh", text: "Tres sectas que difieren sobre la acción humana" },
  "themes.free-will.sum.antiquities.5.172": { fp: "614m4d", text: "Fariseos: unos actos son del destino, otros nuestros" },
  "themes.free-will.sum.antiquities.5.173": { fp: "1urrkg1", text: "Los saduceos niegan el destino: todo es nuestro" },
  "themes.free-will.sum.greco-epictetus-discourses-1.1.1": { fp: "ortfxv", text: "Solo el uso de las apariencias está en nuestro poder" },
  "themes.free-will.sum.origen-principles-3.1.1": { fp: "1vc7963", text: "El juicio supone que está en nuestro poder" },
  "themes.free-will.sum.origen-principles-3.1.3": { fp: "uj269h", text: "La impresión llega sin pedirla; el uso es nuestro" },
  "themes.free-will.sum.tert-soul.21.1": { fp: "psqndc", text: "El libre albedrío puede cambiar un carácter asentado" },
  "themes.godhead.absence.0": { fp: "c1qlfu", text: "La discusión rabínica clásica sobre las «dos poderes en el cielo» está en el Talmud de Babilonia, en Sanedrín 38b —donde el problema es el ángel Metatrón— y en Ḥaguigá 14a. El Bavlí está en esta biblioteca y esas páginas están ahí, pero solo en arameo: la traducción inglesa disponible tiene licencia no comercial y esta aplicación no puede usarla. Así que quien lea arameo puede leerlas en Textos, pero son invisibles para esta página y para la búsqueda, porque ambas se construyen a partir del inglés. Lo que queda aquí es la decisión del Yerushalmí que aparece abajo, donde se manda callar una oración y la razón que se da cabe en dos palabras." },
  "themes.godhead.absence.1": { fp: "815weg", text: "Nadie en esta página defiende la otra posición con su propia voz. Ireneo está refutando a quienes sostenían que el mundo fue hecho por un dios menor que el Padre, y él es la única razón por la que sabemos lo que decían: en esta biblioteca no hay ningún texto marcionita ni valentiniano, y la iglesia que conservó estos manuscritos nunca copió ninguno. Toda posición de dos dioses que aparece aquí está citada por su adversario." },
  "themes.godhead.anchors": { fp: "4dnter", text: "Las anclas son Deuteronomio 6:4 («Escucha, Israel: el SEÑOR nuestro Dios, el SEÑOR es uno»), Deuteronomio 32:39 e Isaías 45:5–7. Son canónicos y quedan fuera de este corpus, pero los Targumim que aparecen abajo los están traduciendo, y casi todo lo demás argumenta a partir de ellos." },
  "themes.godhead.blurb": { fp: "x4hm6n", text: "Todos aquí dicen que Dios es uno. En lo que no coinciden es en qué excluye eso. En Aristeas, un cortesano judío le dice al rey que los griegos adoran al mismo Dios bajo el nombre de Zeus; Josefo, en el mismo estante, se burla de los dioses griegos llamándolos herreros y tejedores. Y esa unicidad tiene costuras desde el principio: Filón encuentra dos poderes en ella, el Targum mete al Verbo dentro del versículo mismo que niega que haya otro Dios, y el Yerushalmí manda callar una oración porque da a entender que son dos. Justino dice después en voz alta lo que aquella liturgia estaba acallando: «otro Dios y Señor», subordinado al Hacedor. Nada de esto es todavía una doctrina de la Trinidad; para eso, véase la página [[Father, Son and Spirit]]." },
  "themes.godhead.label": { fp: "vua6dn", text: "Dios, y si Dios es uno" },
  "themes.godhead.sum.2enoch.33.9": { fp: "c1pntc", text: "Creador de todas las cosas; no hay otro Dios" },
  "themes.godhead.sum.4Macc.5.24": { fp: "1hbgkl0", text: "La ley enseña a adorar a un solo Dios" },
  "themes.godhead.sum.af-1clement.46.6": { fp: "1py6lsu", text: "Un solo Dios, un solo Cristo, un solo Espíritu de gracia" },
  "themes.godhead.sum.af-2clement.20.5": { fp: "ncv4dw", text: "Al único Dios invisible, Padre de la verdad" },
  "themes.godhead.sum.af-ign-ephesians.7.2": { fp: "yvgd0k", text: "Un solo médico: engendrado e ingénito, Dios en el hombre" },
  "themes.godhead.sum.af-ign-magnesians.8.2": { fp: "1fwinqo", text: "Un solo Dios, manifestado por su Hijo, su Verbo" },
  "themes.godhead.sum.against-apion.1.193": { fp: "1qw4ce2", text: "Un templo para un Dios, común a todos" },
  "themes.godhead.sum.against-apion.1.242": { fp: "1qwenwd", text: "Dioses que son herreros, tejedores, guerreros, citaristas" },
  "themes.godhead.sum.anf-irenaeus-1.22.1": { fp: "5wjtqd", text: "Regla de verdad: un solo Dios, que crea por su Verbo" },
  "themes.godhead.sum.anf-irenaeus-4.32.1": { fp: "bcrrts", text: "Ambos testamentos vienen de un solo y mismo Dios" },
  "themes.godhead.sum.antiquities.5.91": { fp: "ws0faa", text: "Primer mandamiento: un solo Dios, adorarlo solo a él" },
  "themes.godhead.sum.aristeas.1.15": { fp: "mgm3kk", text: "Los griegos adoran al mismo Dios, llamándolo Zeus" },
  "themes.godhead.sum.athanasius-arians-3.4.1": { fp: "1dcnx2w", text: "Identidad de deidad, unidad de esencia, dos personas" },
  "themes.godhead.sum.greco-diogenes-laertius.7.135": { fp: "168txwr", text: "Dios identificado con la Razón, el Destino y Zeus" },
  "themes.godhead.sum.justin-dialogue.56.3": { fp: "ll2k80", text: "Otro Dios y Señor, sujeto al Hacedor" },
  "themes.godhead.sum.philo-abraham.1.145": { fp: "2b1ev5", text: "Dos poderes en Dios: el benéfico y el que castiga" },
  "themes.godhead.sum.philo-flight.1.71": { fp: "1v2guz1", text: "«Hagamos al hombre»: habla en plural, un solo Creador" },
  "themes.godhead.sum.plutarch-isis-osiris.67.1": { fp: "1s4ov1r", text: "Una sola razón ordenadora, nombrada distinto por cada nación" },
  "themes.godhead.sum.sibylline.3.12": { fp: "4ha0zp", text: "Dios es uno: soberano, inefable, que habita en el cielo" },
  "themes.godhead.sum.tg-psj-deuteronomy.26.17": { fp: "1s26lcb", text: "Israel confiesa al Señor con una sola confesión" },
  "themes.godhead.sum.tg-psj-deuteronomy.32.39": { fp: "1owd568", text: "No hay otro Dios junto a mí: yo, en mi Verbo" },
  "themes.godhead.sum.y-megillah.4.10": { fp: "1t04kt6", text: "Una oración acallada: da a entender dos poderes" },
  "themes.grace-election.absence.0": { fp: "1ulmlso", text: "Nadie aquí pregunta si un individuo es de los elegidos. En estos textos la pregunta es siempre por un pueblo —qué nación, qué remanente, el pacto de quién— y la pregunta cristiana posterior de si una persona en particular está entre los escogidos, con toda la maquinaria de predestinación y seguridad que la acompaña, sencillamente no se está haciendo. Leerla dentro de «los elegidos» de 1 Enoc o de la «porción escogida» de 1 Clemente es importar una pregunta del siglo V y posteriores." },
  "themes.grace-election.absence.1": { fp: "hwu8ou", text: "La comunidad de Qumrán se entendía a sí misma como el remanente elegido DENTRO de Israel, y esa es la postura que falta en esta página: ni Israel frente a las naciones, ni la iglesia frente a Israel, sino un grupo dentro del pueblo del pacto que se declara la parte verdadera de él. No existe ninguna versión inglesa de los rollos en dominio público ni con licencia abierta, de modo que falta el único cuerpo de evidencia para esa tercera opción." },
  "themes.grace-election.anchors": { fp: "q0n9we", text: "Las anclas son Deuteronomio 7:6–8 (no porque fueran más numerosos, pues eran los menos), Deuteronomio 14:2, Isaías 41:8–9 y Amós 3:2: escogidos y, por eso mismo, castigados. Son canónicos y quedan fuera de este corpus. El Targum de abajo está traduciendo el primero, y lo que hace con «los menos de todos los pueblos» es lo más interesante de esta página." },
  "themes.grace-election.blurb": { fp: "16hjzhi", text: "Ser escogido no es, en estos textos, algo cómodo de sostener. En Jubileos, Dios aparta un pueblo para sí y anota a Jacob como su primogénito. 4 Esdras convierte esa misma idea en una queja: de toda madera, una vid; de todos los pueblos, un pueblo; entonces, ¿por qué somos nosotros los pisoteados? Y luego, cuatro capítulos más adelante, la declaración de gracia más aguda del corpus: que Dios será llamado misericordioso precisamente por nosotros, que no tenemos obras de justicia. El Targum, al traducir un versículo donde el hebreo se niega a dar razón de la elección, da una de todos modos. 1 Clemente toma el mismo vocabulario —una porción escogida, una posesión especial— y lo aplica sin discutirlo a una iglesia gentil." },
  "themes.grace-election.label": { fp: "pyr050", text: "Gracia, elección y los escogidos" },
  "themes.grace-election.sum.1enoch.1.8": { fp: "1ppxj85", text: "Protegerá a los elegidos y les mostrará misericordia" },
  "themes.grace-election.sum.2esdras.5.23": { fp: "1yf9cx", text: "De toda madera, escogiste una vid" },
  "themes.grace-election.sum.2esdras.5.27": { fp: "9c329", text: "De todos los pueblos, te conseguiste uno" },
  "themes.grace-election.sum.2esdras.6.59": { fp: "121yqba", text: "Si fue hecho para nosotros, ¿por qué no lo poseemos?" },
  "themes.grace-election.sum.2esdras.8.31": { fp: "oz8r4x", text: "Por nosotros, pecadores, se te llama misericordioso" },
  "themes.grace-election.sum.2esdras.8.32": { fp: "1l8zh4p", text: "Misericordia para nosotros, que no tenemos obras de justicia" },
  "themes.grace-election.sum.PsSol.9.9": { fp: "hmt6k6", text: "Escogió la simiente de Abraham; no la rechazará para siempre" },
  "themes.grace-election.sum.Sir.47.22": { fp: "qpg88x", text: "No abolirá la descendencia de su escogido" },
  "themes.grace-election.sum.Wis.3.9": { fp: "toxkvg", text: "La gracia y la misericordia son para sus elegidos" },
  "themes.grace-election.sum.af-1clement.29.1": { fp: "1jan40b", text: "Nos hizo para sí una porción escogida" },
  "themes.grace-election.sum.af-1clement.30.1": { fp: "4mops1", text: "Siendo la porción especial, actúen como tal" },
  "themes.grace-election.sum.af-barnabas.6.19": { fp: "1q3nvdd", text: "Para que lleguemos a ser herederos del pacto" },
  "themes.grace-election.sum.jubilees.2.19": { fp: "243qqi", text: "Un pueblo apartado, señalado por el sábado" },
  "themes.grace-election.sum.jubilees.2.20": { fp: "hdvj14", text: "Jacob escogido, anotado como hijo primogénito" },
  "themes.grace-election.sum.m-avot.3.14": { fp: "1ckinp9", text: "Israel amado, y a quien se le dice que lo es" },
  "themes.grace-election.sum.odes-of-solomon.23.2": { fp: "1dtlf5t", text: "La gracia es de quienes confiaron desde el principio" },
  "themes.grace-election.sum.tg-psj-deuteronomy.7.6": { fp: "1d184cx", text: "Un pueblo más amado que todos los pueblos" },
  "themes.grace-election.sum.tg-psj-deuteronomy.7.7": { fp: "mfu25q", text: "Escogidos no por excelencia, sino por humildad" },
  "themes.group.christ": { fp: "eq4uew", text: "Cristo" },
  "themes.group.god-and-the-unseen": { fp: "1gmeo2l", text: "Dios y lo invisible" },
  "themes.group.last-things": { fp: "1hwhb1q", text: "Las últimas cosas" },
  "themes.group.law-and-practice": { fp: "1ptcm3v", text: "La ley y la práctica" },
  "themes.group.people-and-power": { fp: "k7gjaq", text: "El pueblo y el poder" },
  "themes.group.sin-and-salvation": { fp: "gamiy7", text: "El pecado y la salvación" },
  "themes.group.temple-and-community": { fp: "7u2c7s", text: "El templo y la comunidad" },
  "themes.holy-spirit.absence.0": { fp: "mu70ne", text: "La afirmación rabínica que todo el mundo cita —que al morir los últimos profetas, Hageo, Zacarías y Malaquías, el Espíritu Santo cesó en Israel— está en esta biblioteca y no se puede leer en esta página. Es Tosefta Sotá 13, y la Tosefta está aquí solo en hebreo: la versión inglesa disponible es una traducción comunitaria parcial con una licencia que esta aplicación no puede usar. La misma frase reaparece en el Talmud de Babilonia (Yomá 9b, Sanedrín 11a), que está aquí solo en arameo por la misma razón. Así que el corpus guarda el texto y esta página no puede citarlo, y por eso nada de lo que sigue dice que el Espíritu se haya detenido alguna vez." },
  "themes.holy-spirit.absence.1": { fp: "1h06zng", text: "Falta Qumrán, y para este tema esa es la mayor ausencia de todas. La Regla de la Comunidad expone dos espíritus, el de la verdad y el de la mentira, dados a cada persona en cierta medida, y los Himnos de Acción de Gracias hablan de un espíritu santo en el que habla. No existe ninguna versión inglesa de los rollos en dominio público ni con licencia abierta, de modo que aquí no hay nada de ello." },
  "themes.holy-spirit.anchors": { fp: "leq3l3", text: "Las anclas son Números 11:25–29, Isaías 11:2 y 61:1, Joel 2:28–29 y Salmo 51:11. Son canónicos y quedan fuera de este corpus; los Targumim que aparecen abajo están traduciendo dos de ellos, y Bernabé está citando un tercero." },
  "themes.holy-spirit.blurb": { fp: "15zqpxe", text: "Las mismas palabras cubren aquí varias cosas distintas, y distinguirlas es casi todo el trabajo. El Espíritu se apodera de un profeta y le pone palabras en la boca; también hace que un artesano sea bueno en su oficio, huye de un pensamiento deshonesto, reposa sobre el rey que ha de venir y —en una escalera rabínica— es un peldaño al que se sube. Los Targumim lo estrechan deliberadamente, traduciendo el Espíritu divino como «espíritu de profecía», una expresión que no tiene original hebreo. Lo más difícil de encontrar en cualquier parte antes de los escritores cristianos es el Espíritu como alguien y no como algo." },
  "themes.holy-spirit.label": { fp: "1aidkzs", text: "El Espíritu de Dios" },
  "themes.holy-spirit.sum.PsSol.17.37": { fp: "1kt88ff", text: "Al rey venidero lo fortalece el espíritu santo" },
  "themes.holy-spirit.sum.Sir.39.6": { fp: "uy9tj9", text: "El escriba lleno de un espíritu de entendimiento" },
  "themes.holy-spirit.sum.Sus.1.45": { fp: "15pvo4u", text: "Dios despierta el espíritu santo de un muchacho" },
  "themes.holy-spirit.sum.Wis.1.5": { fp: "rprw5d", text: "El espíritu santo huye del engaño y la injusticia" },
  "themes.holy-spirit.sum.Wis.9.17": { fp: "fz800j", text: "El designio de Dios se ignora si él no lo envía" },
  "themes.holy-spirit.sum.af-1clement.2.2": { fp: "13gw97b", text: "Una efusión abundante cayó sobre todos" },
  "themes.holy-spirit.sum.af-barnabas.14.9": { fp: "10r7kk7", text: "El Espíritu está sobre mí: ungido para predicar" },
  "themes.holy-spirit.sum.af-hermas.33.2": { fp: "qt4ldr", text: "El mal genio oscurece al Espíritu que habita dentro" },
  "themes.holy-spirit.sum.af-hermas.43.9": { fp: "1gljm76", text: "Un ángel del espíritu profético lo llena" },
  "themes.holy-spirit.sum.anf-irenaeus-4.20.8": { fp: "ufjppr", text: "El Espíritu mostró a los profetas lo por venir" },
  "themes.holy-spirit.sum.antiquities.6.119": { fp: "de8upb", text: "Balaam: arrebatado, palabras que no son suyas" },
  "themes.holy-spirit.sum.justin-dialogue.88.1": { fp: "pdgykx", text: "Entre nosotros, mujeres y hombres tienen los dones" },
  "themes.holy-spirit.sum.m-sotah.9.15": { fp: "ra1i7", text: "Una escalera de virtudes, el Espíritu casi arriba" },
  "themes.holy-spirit.sum.philo-giants.1.19": { fp: "10st1d7", text: "El Espíritu no permanece entre los carnales" },
  "themes.holy-spirit.sum.philo-giants.1.23": { fp: "o5nu4d", text: "Besalel lleno del Espíritu: para la artesanía" },
  "themes.holy-spirit.sum.tg-isaiah.11.2": { fp: "95ysod", text: "Espíritu de profecía reposando sobre el retoño" },
  "themes.holy-spirit.sum.tg-isaiah.40.13": { fp: "flqdk2", text: "¿Quién dirigió el Espíritu en boca de los profetas?" },
  "themes.holy-spirit.sum.tg-psj-exodus.33.16": { fp: "8vx517", text: "Negado a las naciones: la marca distintiva de Israel" },
  "themes.holy-spirit.sum.tg-psj-genesis.27.5": { fp: "lwjbsx", text: "Rebeca alcanza a oír por el Espíritu Santo" },
  "themes.holy-spirit.sum.tg-psj-numbers.11.25": { fp: "opvx35", text: "Compartido con setenta, y Moisés no pierde nada" },
  "themes.holy-spirit.sum.y-sotah.5.4": { fp: "1r08729", text: "Junto al mar, el menor cantó como Moisés" },
  "themes.justification.absence.0": { fp: "15g7owe", text: "La expresión «obras de la ley» no es vocabulario judío en ninguna parte de esta biblioteca. Aparece dos veces en unos 118.000 pasajes indexados, y las dos veces es un escritor cristiano citando Gálatas. La única otra aparición antigua que se conoce está en Qumrán, en el documento llamado 4QMMT —literalmente, «algunas obras de la ley»—, y ese texto no está aquí, porque no existe ninguna versión inglesa de los rollos en dominio público ni con licencia abierta. Así que la expresión de cuyo sentido depende toda la discusión moderna no puede estudiarse desde este corpus en su entorno no paulino." },
  "themes.justification.absence.1": { fp: "1btahr4", text: "Nadie aquí le está respondiendo a Pablo. Los textos judíos de abajo se escribieron sin referencia a él y en su mayoría antes que él, y los rabínicos vienen de un mundo que había dejado de leerlo; los cristianos lo citan sin que nadie les replique. Quien busque el otro lado de la discusión del siglo I no lo hallará, porque en lo que toca a estas fuentes no hubo discusión: hubo gente diciendo cosas diversas sobre la justicia, y Pablo fue uno de ellos." },
  "themes.justification.anchors": { fp: "1626r3w", text: "El ancla es Génesis 15:6 —Abraham creyó a Dios, y le fue contado por justicia—, que casi todos los textos de abajo citan o desde el cual argumentan. Detrás están Habacuc 2:4, Deuteronomio 6:25 y Salmo 106:31. Son canónicos y quedan fuera de este corpus, igual que Romanos 4, Gálatas 3 y Santiago 2, que son las lecturas que suelen enfrentarse entre sí; lo que importa en esta página es qué aspecto tenían las lecturas que las rodeaban." },
  "themes.justification.blurb": { fp: "1fmf3v9", text: "La antítesis que la mayoría de los lectores trae a este material no es aquella en torno a la cual el material está ordenado. Génesis 15:6 se cita aquí una y otra vez, y 1 Macabeos lo lee como que Abraham fue hallado FIEL bajo prueba; Filón lo lee como confianza y no como razonamiento; el Sirácida dice de un tirón que guardó la ley y que fue hallado fiel. 4 Esdras dice que los justos sacan su recompensa de sus propias obras, y luego, tres versículos después, que la justicia de Dios se mostrará precisamente en tener misericordia de personas que no tienen depósito alguno de buenas obras. 1 Clemente hace lo mismo en capítulos contiguos: no justificados por nuestras propias obras sino por la fe, y en seguida, ¿entonces hemos de dejar de hacer el bien? De ninguna manera. Nadie aquí está eligiendo entre las dos cosas." },
  "themes.justification.label": { fp: "f0sxwz", text: "Justicia, obras y pacto" },
  "themes.justification.sum.1Macc.2.52": { fp: "el0isq", text: "Hallado fiel al ser probado; contado por justicia" },
  "themes.justification.sum.2baruch.14.12": { fp: "gywk3z", text: "Un depósito de obras guardado para ellos en tesoros" },
  "themes.justification.sum.2baruch.51.7": { fp: "10qmw90", text: "Los que han sido salvados por sus obras" },
  "themes.justification.sum.2esdras.8.33": { fp: "led12c", text: "Los justos reciben recompensa de sus obras" },
  "themes.justification.sum.2esdras.8.36": { fp: "1qom94y", text: "Misericordia para los que no tienen depósito de obras" },
  "themes.justification.sum.PsSol.9.2": { fp: "be8mbn", text: "Para que tú, Dios, seas justificado, no nosotros" },
  "themes.justification.sum.Sir.44.20": { fp: "kunzks", text: "Guardó la ley y fue hallado fiel" },
  "themes.justification.sum.af-1clement.32.4": { fp: "1x0qyb5", text: "No justificados por nuestras obras, sino por la fe" },
  "themes.justification.sum.af-1clement.33.1": { fp: "71cxtw", text: "¿Entonces dejamos de hacer el bien? De ninguna manera" },
  "themes.justification.sum.anf-irenaeus-4.21.1": { fp: "28s44m", text: "Abraham, profeta de la fe, citando Gálatas" },
  "themes.justification.sum.clement-stromateis-1.26.1": { fp: "uyduvr", text: "La ley, ayo; Moisés, ley viviente" },
  "themes.justification.sum.m-avot.3.16": { fp: "l0n5ps", text: "El libro está abierto y la mano escribe" },
  "themes.justification.sum.m-sanhedrin.10.1": { fp: "p8u2fv", text: "Todo Israel tiene parte, con excepciones nombradas" },
  "themes.justification.sum.philo-alleg-interp.3.228": { fp: "1bk3wz8", text: "Confía en Dios, no en razonamientos inciertos" },
  "themes.justification.sum.y-peah.1.1": { fp: "hgxqw4", text: "Obras cuyo capital queda para el porvenir" },
  "themes.king-of-israel.absence.0": { fp: "1pgxl0o", text: "Los reyes mismos no dejaron nada. Todo lo que sigue lo escribieron sobre los asmoneos y sobre Herodes personas que vinieron después de ellos o que los detestaban —Josefo antes que nadie, escribiendo bajo mecenazgo romano un siglo más tarde—. En esta biblioteca no se conserva ningún documento asmoneo ni herodiano, y sus monedas e inscripciones, que son la única evidencia contemporánea de cómo se titulaban a sí mismos, no son textos y no se recogen aquí." },
  "themes.king-of-israel.absence.1": { fp: "1tjs5t6", text: "La cuarta secta que aparece abajo falta en su propia voz. Josefo es la única razón por la que sabemos que existió un partido que sostenía que solo Dios era gobernante y que el tributo romano era, por tanto, apostasía; y él los culpa de la destrucción del país. Nada de lo que escribieron se conserva en ninguna parte. La única postura de esta página que hubo que defender al precio de una guerra se conoce únicamente por su testigo más hostil." },
  "themes.king-of-israel.anchors": { fp: "zyd75", text: "Las anclas son 1 Samuel 8 (Israel pide un rey y se le advierte lo que va a quitarle), Deuteronomio 17:14–20 (la ley del rey, que la Misná expone abajo) y Jueces 8:23, donde Gedeón se niega: «el SEÑOR reinará sobre ustedes». Son canónicos y quedan fuera de este corpus, pero la ambivalencia que contienen es toda esta página." },
  "themes.king-of-israel.blurb": { fp: "ypxso4", text: "Casi nadie aquí se siente cómodo con un rey. Josefo acuña una palabra —teocracia— para decir que la constitución de Israel no tiene lugar para uno, y fecha la monarquía desde el momento en que terminó la aristocracia. A los asmoneos se los hace gobernantes «hasta que surgiera un profeta fiel», cláusula que admite que el arreglo es provisional; una generación después Aristóbulo se pone la diadema de todos modos. Roma impone luego una aristocracia, Herodes recibe el título por concesión del Senado, y los rabinos escriben una ley del rey siglos después de que haya uno a quien aplicársela: una ley hecha casi solo de restricciones. Los Salmos de Salomón quieren un rey, pero se cuidan de decir quién es el rey de él." },
  "themes.king-of-israel.label": { fp: "132r1lq", text: "La realeza sobre Israel" },
  "themes.king-of-israel.sum.1Macc.14.41": { fp: "wfurj1", text: "Simón gobierna hasta que surja un profeta fiel" },
  "themes.king-of-israel.sum.PsSol.17.34": { fp: "ml7t6j", text: "Y el Señor mismo es el rey de él" },
  "themes.king-of-israel.sum.PsSol.17.42": { fp: "sw6rat", text: "El rey de Israel a quien Dios conoce" },
  "themes.king-of-israel.sum.against-apion.1.165": { fp: "1356dj4", text: "Una palabra nueva acuñada para ello: teocracia" },
  "themes.king-of-israel.sum.antiquities.1.23": { fp: "1uupghj", text: "Una cuarta secta: Dios es su único gobernante" },
  "themes.king-of-israel.sum.antiquities.11.301": { fp: "wb0aco", text: "Aristóbulo se pone una diadema en la cabeza" },
  "themes.king-of-israel.sum.antiquities.12.268": { fp: "waudop", text: "Saúl: primer rey una vez terminada la aristocracia" },
  "themes.king-of-israel.sum.eusebius-he-3.20.1": { fp: "1pudn18", text: "Herederos campesinos: el reino no es terrenal" },
  "themes.king-of-israel.sum.herodotus-histories-3.80.3": { fp: "q11cas", text: "La monarquía corrompe hasta al mejor de los hombres" },
  "themes.king-of-israel.sum.herodotus-histories-3.82.1": { fp: "1fcq183", text: "Darío responde que la monarquía es lo mejor" },
  "themes.king-of-israel.sum.jewish-war.8.169": { fp: "1w4ndn1", text: "Roma reorganiza el gobierno como aristocracia" },
  "themes.king-of-israel.sum.justin-1apology.11.1": { fp: "rk1iex", text: "Nuestro reino no es el que ustedes temen" },
  "themes.king-of-israel.sum.m-sanhedrin.2.2": { fp: "d4f95u", text: "El rey ni juzga ni es juzgado" },
  "themes.king-of-israel.sum.m-sanhedrin.2.4": { fp: "1g4nv6p", text: "Dieciocho esposas; su camino no tiene límite" },
  "themes.king-of-israel.sum.m-sanhedrin.2.5": { fp: "y10o5f", text: "Nadie puede verlo bañarse ni usar su cetro" },
  "themes.king-of-israel.sum.y-sanhedrin.10.2": { fp: "18mdto9", text: "Tres reyes excluidos del mundo venidero" },
  "themes.messiah.absence.0": { fp: "grza6r", text: "Nada de lo que hay aquí hace divino al mesías ni lo hace morir por el pecado. En 4 Esdras sí muere, pero al término de su reinado, cuando la era acaba, y no se dice que con ello se logre nada. Quien busque un mesías sufriente y expiatorio en el judaísmo del Segundo Templo no lo hallará en esta biblioteca. Conviene fijarse bien en lo que eso NO significa: la muerte expiatoria sí está aquí, dicha con todas sus letras en 4 Macabeos, donde la sangre de los mártires es purificación y propiciación por la nación. La idea existía; simplemente no estaba unida al mesías. La página [[Atonement]] recoge esos pasajes." },
  "themes.messiah.absence.1": { fp: "6r5cpe", text: "La expectativa de DOS mesías, uno de Aarón y otro de Israel, se conoce sobre todo por los Rollos del Mar Muerto, que esta biblioteca todavía no tiene. Los Testamentos de los Doce Patriarcas —un conjunto de discursos de despedida atribuidos a los hijos de Jacob, citados aquí como Testamento de Judá y Testamento de Leví— insinúan una figura sacerdotal junto al rey (Testamento de Leví 8:14), pero falta el cuadro completo." },
  "themes.messiah.anchors": { fp: "pooei5", text: "Las anclas son Números 24:17 (una estrella de Jacob), 2 Samuel 7 (la promesa a David), Isaías 11, Salmo 2 y Salmo 110. Son canónicos y quedan fuera de este corpus; todos los textos de abajo trabajan a partir de ellos." },
  "themes.messiah.blurb": { fp: "1926h2g", text: "Lo que se esperaba, antes de que nadie afirmara que ya había llegado. Estas fuentes no describen una expectativa sino varias: un rey davídico que libra a Jerusalén del dominio extranjero, una figura sacerdotal a su lado, una estrella, un hombre oculto que se revela al final; y en 4 Esdras, un mesías que reina cuatrocientos años y después muere. Conviene leerlas antes de leer los Evangelios, no después." },
  "themes.messiah.label": { fp: "1cn0hce", text: "El Mesías y la expectativa mesiánica" },
  "themes.messiah.sum.2baruch.70.9": { fp: "ppsz4z", text: "Los sobrevivientes entregados al Mesías, siervo de Dios" },
  "themes.messiah.sum.2esdras.7.28": { fp: "mb9y8p", text: "Un mesías revelado, que reina cuatrocientos años" },
  "themes.messiah.sum.PsSol.17.21": { fp: "1im0kft", text: "Levanta a su rey, el hijo de David" },
  "themes.messiah.sum.PsSol.17.30": { fp: "1eq33gn", text: "Purifica Jerusalén; las naciones le sirven" },
  "themes.messiah.sum.PsSol.17.32": { fp: "1tr3v1a", text: "Rey justo, enseñado por Dios, ungido del Señor" },
  "themes.messiah.sum.PsSol.17.34": { fp: "1who78r", text: "El Señor mismo es el rey del mesías" },
  "themes.messiah.sum.af-barnabas.12.10": { fp: "rptcvo", text: "Niega que el mesías sea solamente hijo de David" },
  "themes.messiah.sum.jewish-war.5.312": { fp: "i7wogx", text: "Un oráculo ambiguo: un señor del mundo desde Judea" },
  "themes.messiah.sum.justin-dialogue.49.1": { fp: "ktb7se", text: "Trifón: ungido por elección, y así llegó a ser Cristo" },
  "themes.messiah.sum.justin-dialogue.52.1": { fp: "1h54e38", text: "Dos venidas, argumentadas desde la bendición de Jacob" },
  "themes.messiah.sum.tg-isaiah.10.27": { fp: "1da45md", text: "Las naciones quebrantadas ante el Mesías" },
  "themes.messiah.sum.tg-isaiah.11.6": { fp: "5eoiu8", text: "La paz multiplicada en los días del Mesías" },
  "themes.messiah.sum.tg-isaiah.4.2": { fp: "14bnf05", text: "El Mesías del Señor: gozo y gloria" },
  "themes.messiah.sum.tg-isaiah.9.5": { fp: "p1uxnt", text: "El niño de Isaías 9 leído mesiánicamente" },
  "themes.messiah.sum.tp-judah.24.1": { fp: "1ps43hr", text: "Una estrella se levanta de Jacob en paz" },
  "themes.messiah.sum.tp-judah.24.6": { fp: "7c9cve", text: "Un cetro de justicia que alcanza a los gentiles" },
  "themes.messiah.sum.tp-levi.8.14": { fp: "1h9ae5h", text: "Un rey en Judá que establece un sacerdocio nuevo" },
  "themes.redemption.absence.0": { fp: "17z6tsb", text: "Nadie aquí dice a QUIÉN se paga el rescate. La metáfora implica un destinatario —los rescates de Filón tienen uno, y los de Ptolomeo también— y todo uso teológico de esta biblioteca deja esa casilla vacía. Ireneo es el primer escritor de abajo que advierte el problema, y lo resuelve negando que el captor tuviera derecho alguno desde el principio. Las respuestas cristianas posteriores, que el precio se pagó al diablo, y la reacción contra ellas, quedan fuera de este corpus en ambas direcciones." },
  "themes.redemption.absence.1": { fp: "1a34scm", text: "Falta el jubileo como acontecimiento. Josefo expone abajo el procedimiento con detalle cuidadoso, y la Misná legisla en torno a él: un esclavo hebreo queda libre en el jubileo, diga lo que diga su contrato. Pero todos los textos de esta biblioteca describen la regla y ninguno describe una ocasión. Si el año cincuenta llegó a guardarse alguna vez, nada de lo que hay aquí lo registra ni en un sentido ni en otro, lo que deja a la institución redentora más concreta de la ley sin un solo caso atestiguado detrás." },
  "themes.redemption.anchors": { fp: "zhru67", text: "Las anclas son Éxodo 6:6 y 15:13, Deuteronomio 7:8, Levítico 25 (el pariente redentor y el jubileo), Rut 4, Isaías 43:1 y Salmo 49:7–8. Son canónicos y quedan fuera de este corpus; los Targumim de abajo están traduciendo dos de ellos, y Levítico 25 es la razón de que el sentido comercial nunca desaparezca del todo." },
  "themes.redemption.blurb": { fp: "j6igsa", text: "Esta es una palabra del mercado de esclavos antes que una palabra de la teología, y en este corpus sigue siéndolo casi siempre. Ptolomeo paga veinte dracmas por cabeza para liberar cautivos judíos; Herodes se niega a aceptar precio de redención y se lleva a sus presos igual; un animal impuro se redime por su tasación más una quinta parte. Filón conserva la forma cuando la vuelve hacia adentro: los levitas son el rescate de los primogénitos, el medio siclo el rescate de un alma, y un solo sabio el rescate de uno que no vale nada. Cuando el redentor es Dios, el cuadro lo aporta el éxodo: un dueño que recupera a gente que era suya. Ireneo hace después la pregunta que la metáfora invita —pagado a quién, y con qué derecho— y su respuesta es que a nadie se le compró nada, porque el otro bando nunca poseyó nada legítimamente." },
  "themes.redemption.label": { fp: "1k5q0b9", text: "La redención y el rescate" },
  "themes.redemption.sum.3Macc.7.23": { fp: "eyzfqj", text: "Bendito sea el Redentor de Israel" },
  "themes.redemption.sum.PsSol.9.1": { fp: "18kimw5", text: "Se apartaron del Señor que los redimió" },
  "themes.redemption.sum.af-2clement.17.4": { fp: "1ydosdq", text: "Redimirá a cada uno conforme a sus obras" },
  "themes.redemption.sum.af-barnabas.19.10": { fp: "1n7vabu", text: "Trabaja con tus manos: un rescate por los pecados" },
  "themes.redemption.sum.against-apion.1.45": { fp: "nfdz9", text: "Ptolomeo liberó cautivos y pagó su rescate" },
  "themes.redemption.sum.anf-irenaeus-5.1.1": { fp: "htx72d", text: "Se dio a sí mismo como redención por los cautivos" },
  "themes.redemption.sum.anf-irenaeus-5.2.1": { fp: "1ij78z", text: "No propiedad ajena arrebatada, sino la suya propia" },
  "themes.redemption.sum.antiquities.12.282": { fp: "1662wgb", text: "Cada año cincuenta: deudas perdonadas, esclavos liberados" },
  "themes.redemption.sum.antiquities.12.283": { fp: "9wk4ym", text: "Comprador y vendedor se reúnen y calculan los frutos" },
  "themes.redemption.sum.antiquities.5.156": { fp: "5ftpzj", text: "Herodes rechaza todo precio de redención" },
  "themes.redemption.sum.aristeas.1.20": { fp: "1t78irt", text: "Veinte dracmas por cabeza por cada esclavo" },
  "themes.redemption.sum.m-kiddushin.1.2": { fp: "1wwotf0", text: "Un esclavo hebreo queda libre en el jubileo" },
  "themes.redemption.sum.philo-heir.1.186": { fp: "1lgnpli", text: "Medio siclo, ofrecido como rescate de un alma" },
  "themes.redemption.sum.philo-sacrifices.1.118": { fp: "1vxcmwq", text: "Los levitas tomados como rescate de Israel" },
  "themes.redemption.sum.philo-sacrifices.1.121": { fp: "v0n72x", text: "Todo sabio rescata a uno que no vale nada" },
  "themes.redemption.sum.tg-isaiah.11.11": { fp: "p0ldpc", text: "Por segunda vez, para redimir al remanente" },
  "themes.redemption.sum.tg-psj-exodus.12.42": { fp: "179ta5u", text: "Cuatro noches; la cuarta es la liberación" },
  "themes.redemption.sum.tg-psj-leviticus.27.27": { fp: "1l9m8pz", text: "Redímelo por su tasación, más una quinta parte" },
  "themes.redemption.sum.tp-levi.2.10": { fp: "jtxq9d", text: "Anuncia al que redimirá a Israel" },
  "themes.repentance.absence.0": { fp: "fyw72c", text: "Nadie CONTEMPORÁNEO le responde a Hermas. Limitar al bautizado a un solo arrepentimiento más es la postura más tajante que alguien toma aquí, y la réplica que hay en esta página llega toda una vida después, de Tertuliano, que defiende la misma restricción en lugar de discutirla. Los escritores que pensaron que la iglesia podía perdonar con más largueza —la controversia que siguió a las persecuciones, y la propia postura posterior y más dura de Tertuliano— quedan fuera de este corpus en ambas direcciones." },
  "themes.repentance.absence.1": { fp: "1iqyt5o", text: "Falta el material de Qumrán, y es el único cuerpo de evidencia que mostraría el arrepentimiento como rito comunitario y no como acto individual: la confesión de renovación del pacto de la Regla de la Comunidad, donde toda la asamblea dice a una que han obrado mal. No existe ninguna traducción inglesa de los rollos en dominio público ni con licencia abierta, así que el estante de los Rollos del Mar Muerto de esta biblioteca sigue vacío." },
  "themes.repentance.anchors": { fp: "1l4e1e", text: "Las anclas son Ezequiel 18 y 33, Oseas 14, Joel 2:12–13 y Jonás 3. Son canónicos y quedan fuera de este corpus; el Sirácida y 1 Clemente argumentan directamente desde ellos. La Oración de Manasés tiene un ancla narrativa y no doctrinal: 2 Crónicas 33:12–13 dice que el rey cautivo oró y fue oído, sin decir qué oró. La oración suple las palabras que faltan, y por eso existe." },
  "themes.repentance.blurb": { fp: "1uiymov", text: "Volverse atrás, y si hay un límite a cuántas veces se puede. El Sirácida dice que no lo dejes para después; Sabiduría dice que Dios da lugar para ello a propósito; la Misná dictamina que decir «pecaré y me arrepentiré» hace perder la oportunidad. Después Hermas traza una línea que ninguna fuente judía de aquí traza: al bautizado le concede un arrepentimiento más y ninguno otro. La Oración de Manasés pertenece a otro orden distinto del de todos estos: todo lo demás en esta página habla acerca del arrepentimiento, y la oración lo ejecuta, en la voz del penitente mismo." },
  "themes.repentance.label": { fp: "qgw3a2", text: "El arrepentimiento y el perdón" },
  "themes.repentance.sum.Odes.12.11": { fp: "167eyk2", text: "Doblando la rodilla del corazón, rogando gracia" },
  "themes.repentance.sum.Odes.12.13": { fp: "59nvr4", text: "Perdona; no guardes el mal; Dios de los penitentes" },
  "themes.repentance.sum.Odes.12.7": { fp: "19hkkys", text: "Arrepentimiento dispuesto para los pecadores, para que se salven" },
  "themes.repentance.sum.Odes.12.8": { fp: "1mdm2o2", text: "No dispuesto para los justos, sino para mí" },
  "themes.repentance.sum.Odes.12.9": { fp: "vnw11i", text: "Pecados más numerosos que la arena del mar" },
  "themes.repentance.sum.Sir.17.25": { fp: "135vvex", text: "Vuélvete, deja los pecados, ora ante su rostro" },
  "themes.repentance.sum.Sir.5.7": { fp: "1wrt2p5", text: "No dejes para después el volverte al Señor" },
  "themes.repentance.sum.Wis.12.10": { fp: "pqcsyk", text: "Al juzgar despacio, Dios dio lugar al arrepentimiento" },
  "themes.repentance.sum.af-1clement.7.5": { fp: "1i0tw27", text: "A cada generación se le dio lugar para arrepentirse" },
  "themes.repentance.sum.af-1clement.7.6": { fp: "11hbhpk", text: "Noé lo predicó; los obedientes se salvaron" },
  "themes.repentance.sum.af-2clement.16.1": { fp: "1i2706f", text: "Queda oportunidad mientras todavía hay tiempo" },
  "themes.repentance.sum.af-hermas.110.1": { fp: "o8slvi", text: "El pastor se nombra a sí mismo ángel del arrepentimiento" },
  "themes.repentance.sum.af-hermas.29.8": { fp: "d5xmqq", text: "Al arrepentido se lo recibe, pero no muchas veces" },
  "themes.repentance.sum.aristotle-nicomachean-ethics.7.8": { fp: "9y8l0d", text: "El remordimiento marca la debilidad, no el camino de vuelta" },
  "themes.repentance.sum.josaseneth.10.16": { fp: "kpvkjs", text: "Asenet en cilicio, rociada de ceniza" },
  "themes.repentance.sum.m-yoma.8.8": { fp: "q584h0", text: "El arrepentimiento expía las transgresiones leves" },
  "themes.repentance.sum.m-yoma.8.9": { fp: "67vn6h", text: "Planear pecar y arrepentirse hace perder el arrepentimiento" },
  "themes.repentance.sum.philo-rewards.1.15": { fp: "152wqxv", text: "El arrepentimiento compite por un premio propio" },
  "themes.repentance.sum.philo-rewards.1.169": { fp: "171br5l", text: "Dios defiende la suerte de los que se arrepienten" },
  "themes.repentance.sum.tert-repentance.6.2": { fp: "199xfyp", text: "Asirse del arrepentimiento de una vez por todas" },
  "themes.repentance.sum.tg-isaiah.6.10": { fp: "e8tet2", text: "Corazones embotados, no sea que se vuelvan y sanen" },
  "themes.satan-evil.absence.0": { fp: "huosod", text: "El Testamento de Salomón, abajo, es el texto disparejo de esta página y vale la pena leerlo como tal. No pregunta en absoluto de dónde vino el mal. Da por supuesto un mundo poblado de demonios con nombre y hace, en cambio, preguntas operativas —cuál es tu oficio, bajo qué estrella viajas, qué ángel te frustra— y cada respuesta es una contramedida. Su fecha es de veras incierta (entre el siglo I y el V) y su interés es mágico más que teológico, así que queda al lado de los demás y no entre ellos." },
  "themes.satan-evil.absence.1": { fp: "rptep2", text: "Todo lo que hay aquí, salvo Orígenes, responde la pregunta de pasada —mientras cuenta un relato o resuelve un caso— y ninguno de esos textos se propone conciliar su respuesta con la de otro. Orígenes es el primero que la argumenta como doctrina, y la diferencia de método salta a la vista: parte de una premisa sobre las criaturas racionales, la aplica al diablo como a cualquier otro caso, y llega a la caída como conclusión en lugar de referirla como suceso. Léase al final, y adviértase que lleva una advertencia adjunta: la mayor parte de Sobre los principios solo se conserva en el latín de Rufino, y Rufino dijo que suavizó lo que le pareció herético." },
  "themes.satan-evil.anchors": { fp: "1a716b9", text: "Las anclas son Génesis 3, Génesis 6:1–4, Job 1–2, Zacarías 3:1–2 y 1 Crónicas 21:1 —donde «Satanás» incita a David, frente a 2 Samuel 24:1, donde es la ira misma del SEÑOR—. Son canónicos y quedan fuera de este corpus. Job es el modelo que reescribe Jubileos abajo, con Mastema haciendo el papel de acusador y proponiendo el sacrificio de Isaac." },
  "themes.satan-evil.blurb": { fp: "123din", text: "Cuatro respuestas distintas, y no se combinan. El mal bajó de afuera, cuando cayeron los vigilantes (1 Enoc, Jubileos). Vino de Adán, y lo heredamos como un corazón malvado (4 Esdras). Es una facultad dentro de cada persona, la inclinación al mal, con otra buena al lado (la Misná, los Testamentos). O empezó por envidia: el diablo fue expulsado por negarse a inclinarse ante Adán, y desde entonces lo odia (la Vida de Adán y Eva). El Sirácida las descarta todas en dos líneas: no digas que el Señor te hizo caer. Y Celso, desde afuera, opina que todo ese aparato es la confesión de que el Dios de ustedes no da abasto." },
  "themes.satan-evil.label": { fp: "1jlyjq1", text: "Satanás y el origen del mal" },
  "themes.satan-evil.sum.1enoch.54.6": { fp: "bcoamy", text: "Los cuatro arcángeles los echan al horno" },
  "themes.satan-evil.sum.2enoch.31.4": { fp: "1ottls5", text: "Satanail es expulsado; su inteligencia queda intacta" },
  "themes.satan-evil.sum.2esdras.3.21": { fp: "78uyna", text: "El corazón malvado de Adán, y todos los nacidos después" },
  "themes.satan-evil.sum.2esdras.7.118": { fp: "11gccwk", text: "Tú pecaste, y el mal cayó sobre todos" },
  "themes.satan-evil.sum.Sir.15.11": { fp: "fn55yr", text: "No digas que el Señor te hizo caer" },
  "themes.satan-evil.sum.Sir.15.14": { fp: "jsd88w", text: "Dejado desde el principio en su propio albedrío" },
  "themes.satan-evil.sum.Wis.2.24": { fp: "1yj222l", text: "La muerte entró en el mundo por la envidia del diablo" },
  "themes.satan-evil.sum.af-barnabas.18.1": { fp: "2bej8", text: "Dos caminos, con ángeles apostados en cada uno" },
  "themes.satan-evil.sum.af-ign-ephesians.13.1": { fp: "vb2gry", text: "Reunirse derriba los poderes de Satanás" },
  "themes.satan-evil.sum.af-polycarp.7.1": { fp: "1qbzp8y", text: "Negar la cruz te hace del diablo" },
  "themes.satan-evil.sum.jubilees.10.6": { fp: "8fkoba", text: "Mastema negocia para quedarse con una décima parte" },
  "themes.satan-evil.sum.jubilees.17.16": { fp: "1c60hc", text: "Mastema propone el sacrificio de Isaac" },
  "themes.satan-evil.sum.lae.12.1": { fp: "1yxam48", text: "Toda mi hostilidad y mi envidia son para ti" },
  "themes.satan-evil.sum.lae.14.3": { fp: "1ud7226", text: "No adoraré a un ser posterior e inferior" },
  "themes.satan-evil.sum.m-avot.2.11": { fp: "1wps1ow", text: "Mal ojo, mala inclinación, odio: tres destructores" },
  "themes.satan-evil.sum.m-yoma.4.1": { fp: "owtzje", text: "La urna, las dos suertes, el macho cabrío" },
  "themes.satan-evil.sum.origen-celsus-6.42.1": { fp: "1tg5c83", text: "Celso: un adversario significa que tu Dios no puede" },
  "themes.satan-evil.sum.origen-principles-1.5.2": { fp: "1e97ip5", text: "La regla vale para el diablo como para cualquiera" },
  "themes.satan-evil.sum.origen-principles-1.5.5": { fp: "1vj3qel", text: "El Lucifer de Isaías leído como la caída misma" },
  "themes.satan-evil.sum.origen-principles-1.8.3": { fp: "1tixvan", text: "Poder admitir el mal no es ser malo" },
  "themes.satan-evil.sum.plutarch-isis-osiris.46.1": { fp: "1yf52fa", text: "Los dos dioses de Zoroastro: luz contra tiniebla de brea" },
  "themes.satan-evil.sum.testament-of-solomon.22.1": { fp: "no50ub", text: "Asmodeo se nombra y declara su oficio" },
  "themes.satan-evil.sum.testament-of-solomon.24.1": { fp: "10dzm99", text: "Rafael lo frustra, y el hígado de un pez" },
  "themes.satan-evil.sum.testament-of-solomon.35.1": { fp: "1kopelr", text: "Engaño, el primero de siete, tejiendo lazos" },
  "themes.satan-evil.sum.tg-psj-genesis.3.6": { fp: "1i6cqfa", text: "Eva ve a Samael, el ángel de la muerte" },
  "themes.satan-evil.sum.tg-psj-leviticus.16.8": { fp: "1mk9nz3", text: "Una suerte para el Nombre, otra para Azazel" },
  "themes.satan-evil.sum.tp-asher.1.8": { fp: "13ld8ty", text: "Inclinado a la mala inclinación, dominado por Beliar" },
  "themes.sin-fall.absence.0": { fp: "kpuy56", text: "La expresión «pecado original» no aparece en ninguna parte de este corpus: ni una sola vez en unos 118.000 pasajes indexados. La doctrina bajo ese nombre es de Agustín, del siglo V y en latín, y ningún texto de aquí la formula. 4 Esdras es lo que más se acerca, y 2 Baruc lo contradice. Un estudiante no debería leer la categoría posterior dentro de estas frases: son anteriores a ella y están menos asentadas que ella." },
  "themes.sin-fall.absence.1": { fp: "1iw1jhg", text: "Los dos textos que llevan el peso de la discusión están lejos de sus originales. 4 Esdras —capítulos 3–14 de 2 Esdras— se conserva en latín, traducido de un griego que se perdió, hecho a su vez de un hebreo o arameo que también se perdió. 2 Baruc se conserva en siríaco, en esencia en un solo manuscrito. Ambos se leen aquí en el inglés de R. H. Charles. Cuando una sola palabra sostiene un argumento, eso son cuatro lenguas de distancia." },
  "themes.sin-fall.absence.2": { fp: "ip802o", text: "La otra respuesta judía no está en esta página. Buena parte de este corpus explica el mal obrar por una inclinación al mal presente en todos, y no por algo que hiciera Adán, con lo cual la caída queda casi al margen. Esos pasajes —la Misná, los Testamentos— se exponen en la página [[Satan]]." },
  "themes.sin-fall.anchors": { fp: "zag0jd", text: "Las anclas son Génesis 2–3, Génesis 6:5, Salmo 51:5 y Eclesiastés 7:20. Son canónicos y quedan fuera de este corpus. Romanos 5:12–21 y 1 Corintios 15:21–22 son los textos del Nuevo Testamento con los que suele leerse este material, e Ireneo, abajo, cita el primero casi al pie de la letra." },
  "themes.sin-fall.blurb": { fp: "1y236mm", text: "¿Lo que hizo Adán cambió lo que somos? Dos apocalipsis judíos escritos con una generación de diferencia responden de maneras opuestas, y uno de ellos responde de las dos. 4 Esdras dice que un corazón malvado creció en nosotros desde el primer Adán y se ha llevado a casi todos; 2 Baruc clama «oh Adán, ¿qué has hecho a todos los que nacen de ti?», y después, treinta capítulos más adelante, dice que Adán no es causa del alma de nadie sino de la suya, y que cada uno de nosotros es su propio Adán. El Sirácida culpa a Eva en un capítulo y al orgullo en otro. Los Targumim convierten todo el asunto en una lección sobre guardar los mandamientos. Después Ireneo lo lee como la desobediencia de un hombre deshecha por la obediencia de un hombre, y Atanasio argumenta desde la Sabiduría de Salomón." },
  "themes.sin-fall.label": { fp: "1uqbz2c", text: "El pecado y la caída" },
  "themes.sin-fall.sum.2baruch.17.2": { fp: "n6a23h", text: "Novecientos años, y no le aprovechó de nada" },
  "themes.sin-fall.sum.2baruch.23.4": { fp: "1uup4nw", text: "Adán pecó; se decretó la muerte sobre los no nacidos" },
  "themes.sin-fall.sum.2baruch.48.42": { fp: "ixp9lr", text: "Oh Adán, ¿qué les has hecho a todos?" },
  "themes.sin-fall.sum.2baruch.54.19": { fp: "souex6", text: "Cada uno de nosotros ha sido su propio Adán" },
  "themes.sin-fall.sum.2esdras.3.21": { fp: "b19gmh", text: "El corazón malvado del primer Adán, y su descendencia" },
  "themes.sin-fall.sum.2esdras.7.11": { fp: "14euieb", text: "Adán transgredió, y el mundo fue juzgado" },
  "themes.sin-fall.sum.2esdras.7.48": { fp: "18d7vsg", text: "Un corazón malvado en nosotros, en casi todos" },
  "themes.sin-fall.sum.Sir.10.13": { fp: "y55qkm", text: "El orgullo, en otro lugar, es el principio del pecado" },
  "themes.sin-fall.sum.Sir.25.24": { fp: "1w3b0hh", text: "De la mujer comenzó el pecado; todos morimos" },
  "themes.sin-fall.sum.anf-irenaeus-3.21.10": { fp: "i562tv", text: "La desobediencia de un hombre, la obediencia de un hombre" },
  "themes.sin-fall.sum.anf-irenaeus-3.23.1": { fp: "795gje", text: "La recapitulación alcanza hacia atrás para salvar a Adán" },
  "themes.sin-fall.sum.apocmoses.32.2": { fp: "101k60p", text: "Eva confiesa: todo pecado comenzó por mí" },
  "themes.sin-fall.sum.athanasius-incarnation.3.1": { fp: "15ujlsd", text: "Una ley en el huerto, con la muerte adjunta" },
  "themes.sin-fall.sum.athanasius-incarnation.5.1": { fp: "1wjbzzc", text: "La corrupción ganó más que su poder natural" },
  "themes.sin-fall.sum.hesiod-works-and-days.1.80": { fp: "1sidb8v", text: "Pandora, hecha y dada como plaga a los hombres" },
  "themes.sin-fall.sum.hesiod-works-and-days.1.90": { fp: "ilzlcj", text: "Ella levanta la tapa; antes de eso, ningún mal" },
  "themes.sin-fall.sum.lae.44.2": { fp: "1dbe4ei", text: "Adán a Eva: pecado para todas nuestras generaciones" },
  "themes.sin-fall.sum.tg-psj-genesis.3.15": { fp: "osaoif", text: "Aplastar la serpiente depende de guardar la Torá" },
  "themes.sin-fall.sum.tg-psj-genesis.3.19": { fp: "1o0bwcw", text: "Polvo, y del polvo, levantado para el juicio" },
  "themes.sin-fall.sum.tg-psj-genesis.3.22": { fp: "1jzmcmb", text: "Si los hubiera guardado, habría vivido" },
  "themes.son-of-david.absence.0": { fp: "1c7swyd", text: "Ningún texto de esta biblioteca contiene una genealogía davídica real. Todos afirman el linaje y nadie expone la línea, que es exactamente lo que cabría predecir del informe de Eusebio sobre los archivos quemados, y significa que la afirmación no puede comprobarse desde ninguna fuente de aquí. Lo que queda es una afirmación, una discusión sobre dos listas que se contradicen, y una familia de pequeños agricultores de Galilea que dijeron que sí cuando un emperador les preguntó." },
  "themes.son-of-david.absence.1": { fp: "u16wxm", text: "Falta el otro lado de la cuestión. Los argumentos judíos antiguos más claros CONTRA el linaje davídico de Jesús solo los citan los cristianos que los responden —Trifón, en Justino, concede que el mesías será davídico y discute casi todo lo demás— y ningún texto judío de este corpus se enfrenta directamente con la afirmación." },
  "themes.son-of-david.anchors": { fp: "1s2hom", text: "Las anclas son 2 Samuel 7:12–16 (tu trono será firme para siempre), Isaías 11:1 (un retoño del tronco de Isaí), Jeremías 23:5 y 33:17 y —tirando en sentido contrario— Jeremías 22:24–30, la maldición sobre Jeconías, que Ireneo, abajo, tiene que sortear con argumentos. Las dos genealogías de Jesús, Mateo 1 y Lucas 3, son igualmente canónicas y quedan fuera de este corpus; Eusebio, abajo, intenta armonizarlas." },
  "themes.son-of-david.blurb": { fp: "1m8n0ix", text: "Una afirmación que se hizo más fuerte a medida que se hacía menos verosímil. El Sirácida enuncia el principio dinástico —la realeza pertenece solo a la posteridad de David, como el sacerdocio a la de Aarón— y Josefo cuenta después los reyes del linaje de David y se detiene. Tras el destierro, el único davídida en el cargo es Zorobabel. Los Salmos de Salomón piden un hijo de David precisamente porque el trono lo ha tomado gente sin derecho a él; y cuando el último asmoneo objeta contra Herodes, apela a su propia familia, no a la de David. Herodes quema entonces los archivos genealógicos. Para cuando los cristianos afirman el linaje, ya nadie habría podido comprobarlo, y Bernabé dice que de todos modos no importa." },
  "themes.son-of-david.label": { fp: "gwue1m", text: "Hijo de David" },
  "themes.son-of-david.sum.1Esd.5.5": { fp: "1mgvv2i", text: "Zorobabel, de la casa de David, de regreso" },
  "themes.son-of-david.sum.PsSol.17.21": { fp: "1im0kft", text: "Levanta a su rey, el hijo de David" },
  "themes.son-of-david.sum.PsSol.17.4": { fp: "awmlfp", text: "Dios juró que el reino de David no faltaría" },
  "themes.son-of-david.sum.PsSol.17.6": { fp: "ju785w", text: "Usurpadores asolaron el trono de David" },
  "themes.son-of-david.sum.Sir.45.25": { fp: "py6sgr", text: "La realeza a la descendencia de David como el sacerdocio a la de Aarón" },
  "themes.son-of-david.sum.Sir.48.15": { fp: "t9tgan", text: "Tras el destierro, todavía un gobernante en la casa de David" },
  "themes.son-of-david.sum.af-barnabas.12.10": { fp: "38ccs8", text: "Llamarlo hijo de David es el error" },
  "themes.son-of-david.sum.af-ign-ephesians.18.2": { fp: "1n320qr", text: "De la simiente de David y del Espíritu Santo" },
  "themes.son-of-david.sum.af-ign-romans.7.3": { fp: "g7ys3v", text: "El pan de Dios: carne de la simiente de David" },
  "themes.son-of-david.sum.anf-irenaeus-3.21.9": { fp: "12c2r2s", text: "La maldición de Jeconías: el hijo de José no podía heredar" },
  "themes.son-of-david.sum.antiquities.15.403": { fp: "dbvi4u", text: "A Herodes se le objeta ser un particular y medio judío" },
  "themes.son-of-david.sum.antiquities.8.143": { fp: "1wl0e0g", text: "Veintiún reyes del linaje de David, y luego ninguno" },
  "themes.son-of-david.sum.eusebius-he-1.7.1": { fp: "3nnkzn", text: "Herodes quemó los archivos, ocultando su origen humilde" },
  "themes.son-of-david.sum.eusebius-he-3.20.1": { fp: "aypynu", text: "Domiciano interroga a los nietos de Judas y les ve las manos" },
  "themes.son-of-david.sum.tg-isaiah.22.22": { fp: "dts7n7", text: "La llave de la casa de David puesta en su mano" },
  "themes.son-of-david.sum.tg-isaiah.8.6": { fp: "jt4hj9", text: "El pueblo rechaza el gobierno de la casa de David" },
  "themes.son-of-david.sum.tg-isaiah.9.6": { fp: "4wg55a", text: "El trono de David no tendrá fin" },
  "themes.son-of-god.absence.0": { fp: "1h88424", text: "El paralelo verbal más cercano a los Evangelios está en Qumrán y no está aquí. 4Q246, un fragmento arameo, dice de una figura venidera que «será llamado Hijo de Dios, y lo llamarán hijo del Altísimo»: el mismo par de expresiones, en el mismo orden, que Lucas 1:32–35. Si su sujeto es un mesías o un rey extranjero se sigue discutiendo. No existe ninguna versión inglesa de los rollos en dominio público ni con licencia abierta, así que el texto que un estudiante más necesita para este tema es justamente el que no puede leer aquí." },
  "themes.son-of-god.absence.1": { fp: "1epspxa", text: "Cuidado con 2 Esdras en esta página. Sus capítulos 3–14 son un apocalipsis judío de hacia el año 100 d. C., pero los capítulos 1–2 y 15–16 son añadidos cristianos posteriores, y es en el capítulo 2 donde aparece la expresión «el Hijo de Dios, a quien han confesado en el mundo». Citada como evidencia judía probaría lo contrario de lo que parece. Nada de esos capítulos se cita abajo." },
  "themes.son-of-god.anchors": { fp: "1fs4gr2", text: "Las anclas son Éxodo 4:22 (Israel es mi hijo primogénito), 2 Samuel 7:14 y Salmo 2:7 («tú eres mi hijo, yo te engendré hoy», dicho al rey en su entronización), Oseas 11:1 y Génesis 6:2. Son canónicos y quedan fuera de este corpus. 1 Clemente, abajo, cita el Salmo 2:7 sin más, y vale la pena notarlo: el versículo que aplica a Cristo era en origen una fórmula de coronación para un hombre." },
  "themes.son-of-god.blurb": { fp: "uec6b6", text: "En las fuentes judías esto es una relación, y se ofrece ampliamente. Israel es el hijo primogénito de Dios; el hombre que provee para los huérfanos llega a ser «como hijo del Altísimo»; quien vive virtuosamente está entre los hijos de Dios; los ángeles son hijos de Dios en Génesis 6, que es como los lee 1 Enoc. Filón, buscando algo más, le da el título al Logos y en seguida admite que quizá ningún ser humano sea digno de él. El único texto que se acerca al uso de los Evangelios es Sabiduría 2, donde el justo llama padre suyo a Dios y sus enemigos deciden probar si Dios de veras lo va a rescatar. Los escritores cristianos lo convierten después en título de una sola persona, y pasan los tres siglos siguientes explicando en qué se distingue eso de que se lo apliquen a todos los demás." },
  "themes.son-of-god.label": { fp: "62dtkq", text: "Hijo de Dios" },
  "themes.son-of-god.sum.1enoch.106.5": { fp: "mwqxem", text: "El nacimiento de Noé: se parece a los hijos del cielo" },
  "themes.son-of-god.sum.Sir.4.10": { fp: "wdm3go", text: "Cuida de los huérfanos y serás hijo del Altísimo" },
  "themes.son-of-god.sum.Wis.2.16": { fp: "13gnj65", text: "Se jacta de que Dios es su padre" },
  "themes.son-of-god.sum.Wis.2.18": { fp: "mq92jy", text: "Si es hijo de Dios, Dios lo rescatará" },
  "themes.son-of-god.sum.af-1clement.36.4": { fp: "1ftcius", text: "Salmo 2 aplicado: hoy yo te he engendrado" },
  "themes.son-of-god.sum.af-hermas.58.5": { fp: "16cjgpl", text: "¿Por qué se muestra al Hijo de Dios como siervo?" },
  "themes.son-of-god.sum.af-ign-ephesians.20.2": { fp: "7mnwla", text: "Hijo del Hombre e Hijo de Dios a la vez" },
  "themes.son-of-god.sum.af-mart-polycarp.17.3": { fp: "y7wi66", text: "A él lo adoramos; a los mártires solo los queremos" },
  "themes.son-of-god.sum.athanasius-arians-2.59.1": { fp: "1nb8pa", text: "Hechos hijos por llamamiento; él es Hijo por naturaleza" },
  "themes.son-of-god.sum.greco-epictetus-discourses-1.9.1": { fp: "16ay2m5", text: "Los filósofos dicen que Dios y el hombre son parientes" },
  "themes.son-of-god.sum.origen-celsus-8.14.1": { fp: "1qj8mtp", text: "Celso: dejen al Hijo, adoren solo al Padre" },
  "themes.son-of-god.sum.philo-confusion.1.146": { fp: "ltpzmd", text: "Nadie digno aún; déjate formar por su Verbo primogénito" },
  "themes.son-of-god.sum.philo-confusion.1.147": { fp: "1hlutdf", text: "Todavía no hijos de Dios; al menos, hijos" },
  "themes.son-of-god.sum.philo-spec-laws.1.318": { fp: "1mnlqka", text: "Quienes viven virtuosamente son hijos de Dios" },
  "themes.son-of-god.sum.tg-psj-exodus.4.22": { fp: "1k1bf3e", text: "Israel es mi hijo primogénito" },
  "themes.son-of-man.absence.0": { fp: "2v0dn8", text: "El problema de la datación es lo que hay que saber, y es un hueco en la evidencia, no en esta biblioteca. Las Parábolas de Enoc —capítulos 37–71, todo el material del Hijo del Hombre que aparece abajo— son la ÚNICA sección de 1 Enoc de la que no se halló ninguna copia en Qumrán, mientras que de todas las demás sí. Así que no podemos demostrar que esta figura se leyera en el siglo I, y los especialistas fechan las Parábolas en cualquier punto entre el siglo I a. C. y el final del I d. C. Si son trasfondo de los Evangelios o un paralelo a ellos es una cuestión realmente abierta. La página [[Messiah]] cubre lo que se esperaba sin esta figura." },
  "themes.son-of-man.absence.1": { fp: "jjue3", text: "Los rabinos no lo usan como título. Hay una discusión más, sobre Daniel 7:13 y sobre cómo podría haber un segundo trono junto al de Dios, en el Talmud de Babilonia, en Sanedrín 98a, que está en esta biblioteca solo en arameo, porque su versión inglesa tiene licencia no comercial. Los pasajes del Targum que aparecen abajo muestran que el modismo corriente sobrevive, y nada más que eso." },
  "themes.son-of-man.anchors": { fp: "111ekdr", text: "Todo lo que hay aquí sale de Daniel 7:13–14 —uno como hijo de hombre, que viene con las nubes, a quien se le da el dominio—, leído junto con Salmo 8:4 y con Ezequiel, donde Dios se dirige al profeta como «hijo de hombre» unas noventa veces y quiere decir sencillamente «mortal». Daniel es canónico y queda fuera de este corpus. Conviene notar que es además uno de los dos libros bíblicos de los que nunca se hizo Targum, de modo que no hay ninguna traducción judía antigua de ese versículo que consultar." },
  "themes.son-of-man.blurb": { fp: "1wi5xoi", text: "Dos cosas bastante distintas comparten estas palabras. De ordinario, «hijo de hombre» es el modo semítico de decir un ser humano, y por lo general uno frágil: el Sirácida lo usa para decir que no somos inmortales, y Judit para decir que Dios no es de los que vacilan. Después, en las Parábolas de Enoc, se vuelve el título de alguien: una figura determinada, siempre «aquel Hijo del Hombre», escondido junto a Dios antes de la creación, sentado en el trono de gloria, a quien se le entrega el juicio y a quien los reyes adoran. 4 Esdras ve subir del mar a esa misma figura y Dios lo llama «mi Hijo». Y luego el libro del propio Enoc, ya al final, le dice a Enoc que ese hombre es él." },
  "themes.son-of-man.label": { fp: "36w359", text: "El Hijo del Hombre" },
  "themes.son-of-man.sum.1enoch.46.2": { fp: "1cuvqd5", text: "¿Quién es aquel Hijo del Hombre, y de dónde?" },
  "themes.son-of-man.sum.1enoch.46.4": { fp: "n4gjm", text: "Destrona a los reyes y quebranta a los fuertes" },
  "themes.son-of-man.sum.1enoch.48.2": { fp: "awzg5g", text: "Nombrado ante el Anciano de Días" },
  "themes.son-of-man.sum.1enoch.62.5": { fp: "1cu3rhq", text: "Visto en el trono de su gloria" },
  "themes.son-of-man.sum.1enoch.62.7": { fp: "1bflufs", text: "Oculto desde el principio, revelado a los escogidos" },
  "themes.son-of-man.sum.1enoch.62.9": { fp: "1mlafqp", text: "Los reyes caen, adoran y piden misericordia" },
  "themes.son-of-man.sum.1enoch.69.27": { fp: "1ew37t0", text: "La totalidad del juicio se le entrega" },
  "themes.son-of-man.sum.1enoch.71.14": { fp: "ykgfgr", text: "El ángel le dice a Enoc: ese eres tú" },
  "themes.son-of-man.sum.2esdras.13.3": { fp: "1f401q5", text: "Un hombre que sale del mar, volando con las nubes" },
  "themes.son-of-man.sum.2esdras.13.32": { fp: "l2cypu", text: "Dios llama «mi Hijo» al hombre que asciende" },
  "themes.son-of-man.sum.Jdt.8.16": { fp: "glg77m", text: "Dios no es hijo de hombre, para vacilar" },
  "themes.son-of-man.sum.Sir.17.30": { fp: "1786fgm", text: "Modismo llano: el hijo de hombre es mortal" },
  "themes.son-of-man.sum.af-barnabas.12.10": { fp: "1xx3iz9", text: "No hijo de hombre, sino Hijo de Dios" },
  "themes.son-of-man.sum.af-ign-ephesians.20.2": { fp: "1obe2ga", text: "Del linaje de David, Hijo del Hombre e Hijo de Dios" },
  "themes.son-of-man.sum.tg-isaiah.51.12": { fp: "guqi7h", text: "Modismo intacto: un hijo de hombre, como la hierba" },
  "themes.son-of-man.sum.tg-isaiah.56.2": { fp: "pdnevj", text: "El hijo de hombre que guarda el sábado" },
  "themes.tradition.apostolic-fathers.dates": { fp: "99nefv", text: "c. 95 – 150 d. C." },
  "themes.tradition.apostolic-fathers.label": { fp: "dtsllu", text: "Padres apostólicos" },
  "themes.tradition.apostolic-fathers.note": { fp: "5phb3l", text: "Los escritos cristianos más antiguos fuera del Nuevo Testamento, que se traslapan con la última parte de este." },
  "themes.tradition.church-fathers.dates": { fp: "uza3ap", text: "c. 150 – 400 d. C." },
  "themes.tradition.church-fathers.label": { fp: "1dae9ji", text: "Escritores cristianos posteriores" },
  "themes.tradition.church-fathers.note": { fp: "1gupyqr", text: "La discusión cristiana una vez que las preguntas se han endurecido hasta volverse controversia." },
  "themes.tradition.greco-roman.dates": { fp: "1ne0dnr", text: "c. 400 a. C. – 200 d. C." },
  "themes.tradition.greco-roman.label": { fp: "1pjd16j", text: "Griego y romano" },
  "themes.tradition.greco-roman.note": { fp: "xi71qw", text: "El mundo filosófico circundante, cuya esperanza para el alma no es la esperanza judía para el cuerpo." },
  "themes.tradition.rabbinic.dates": { fp: "7o0xr", text: "c. 200 – 600 d. C." },
  "themes.tradition.rabbinic.label": { fp: "1vhmkcr", text: "Rabínico" },
  "themes.tradition.rabbinic.note": { fp: "1hkd6ns", text: "Posterior al Nuevo Testamento. Es evidencia de cómo se asentó el judaísmo, no de lo que sostenía en el siglo I." },
  "themes.tradition.second-temple.dates": { fp: "1yv2ddb", text: "c. 300 a. C. – 100 d. C." },
  "themes.tradition.second-temple.label": { fp: "mvdehc", text: "Judaísmo del Segundo Templo" },
  "themes.tradition.second-temple.note": { fp: "1qedg9h", text: "Escritos judíos de entre los Testamentos y de poco después: el mundo dentro del cual se escribe el Nuevo Testamento." },
  "themes.trinity.absence.0": { fp: "11f151y", text: "No hay material judío ni rabínico en esta página, y eso es un resultado, no un hueco de la búsqueda. Consultar este corpus en busca de lenguaje triádico devuelve muchos resultados del Segundo Templo y rabínicos, y todos ellos están contando hasta tres a propósito de otra cosa: una mesa triple en Josefo, tres hombres que pueden dar gracias juntos en la Misná, Filón sobre las propiedades del número tres. El único pasaje que aparece abajo es lo más cercano que guardan las fuentes judías, y es una oración sobre cómo podría alguien conocer el designio de Dios, no una afirmación sobre la vida interior de Dios." },
  "themes.trinity.absence.1": { fp: "1gb9mpe", text: "Nadie aquí defiende la doctrina en los términos en que la formularía un credo. Tertuliano, abajo, es el que más se acerca, y hace algo distinto de Atanasio: defiende una dispensación —una οἰκονομία, un arreglo— contra quienes pensaban que el Padre mismo nació y padeció, y su propia explicación de por qué lo pensaban es que a la mayoría de los creyentes se les había enseñado a resguardar la unidad. El vocabulario de persona y sustancia se está armando aquí, dentro de una discusión, y todavía no se hereda." },
  "themes.trinity.absence.2": { fp: "5jfhcs", text: "Nada de lo que hay aquí es el Credo Niceno. Atanasio argumenta abriéndose paso hacia él y contra Arrio, pero los textos conciliares mismos —Nicea en 325, Constantinopla en 381— pertenecen a un género que esta biblioteca no colecciona." },
  "themes.trinity.anchors": { fp: "6072vu", text: "Las anclas son Mateo 28:19 («bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo»), 2 Corintios 13:14 y 1 Corintios 12:4–6. Son canónicos y quedan fuera de este corpus, y la Didajé que aparece abajo está citando el primero casi palabra por palabra, que es justamente lo que importa: lo que tienen los escritores más antiguos es esa frase, no una teoría sobre ella." },
  "themes.trinity.blurb": { fp: "rsg92i", text: "Lenguaje triádico antes de los credos. Leídos en orden, estos pasajes muestran una fórmula que llega mucho antes que una doctrina: la Didajé y 1 Clemente nombran a los tres y no explican nada; Justino los jerarquiza —y mete a los ángeles en la lista, entre el Hijo y el Espíritu—; Teófilo es el primer escritor, en cualquier parte, que los llama una τριάς, y lo hace mientras explica los tres primeros días de la creación; Tertuliano tiene después que argumentarlo contra quienes sostenían que el Padre mismo nació y murió, y cuenta que a los creyentes comunes la idea entera les resultaba alarmante. Solo con Atanasio el vocabulario de la esencia y el origen se usa como moneda corriente. Lo que casi nadie hace aquí es afirmar que los tres son un solo Dios en el sentido que tendrá Nicea; eso se está elaborando, en público, contra adversarios." },
  "themes.trinity.label": { fp: "ipymq1", text: "Padre, Hijo y Espíritu" },
  "themes.trinity.sum.Wis.9.17": { fp: "xnljf5", text: "Dios da la sabiduría y envía su Espíritu" },
  "themes.trinity.sum.af-1clement.58.2": { fp: "cc1oe5", text: "Un juramento por los tres a la vez" },
  "themes.trinity.sum.af-didache.7.1": { fp: "1cjyllz", text: "Bautizar en el Padre, el Hijo y el Espíritu Santo" },
  "themes.trinity.sum.af-ign-magnesians.13.1": { fp: "1aunrbp", text: "En el Hijo y el Padre y el Espíritu" },
  "themes.trinity.sum.af-mart-polycarp.14.3": { fp: "9ncpp3", text: "Oración al morir: gloria por él, con él y el Espíritu" },
  "themes.trinity.sum.athanasius-arians-1.6.1": { fp: "rkwwuu", text: "Arrio: el Verbo es Dios solo de nombre" },
  "themes.trinity.sum.athanasius-arians-3.15.1": { fp: "neohhh", text: "No tres orígenes: el sol y su resplandor" },
  "themes.trinity.sum.eusebius-pe-11.20.1": { fp: "a8t14p", text: "El Espíritu en tercer lugar, comparado con el tercero de Platón" },
  "themes.trinity.sum.justin-1apology.6.1": { fp: "1nw7mau", text: "Culto al Padre, al Hijo, a los ángeles y al Espíritu profético" },
  "themes.trinity.sum.justin-1apology.61.1": { fp: "bjyk15", text: "Lavamiento en el nombre de los tres" },
  "themes.trinity.sum.origen-celsus-8.12.1": { fp: "1vdwg", text: "Celso: ustedes honran a un siervo junto a Dios" },
  "themes.trinity.sum.tert-praxeas.12.2": { fp: "1wffyp1", text: "«Hagamos al hombre»: ¿por qué el plural?" },
  "themes.trinity.sum.tert-praxeas.2.1": { fp: "1hja7zw", text: "Un solo Dios bajo una dispensación: una οἰκονομία" },
  "themes.trinity.sum.tert-praxeas.3.1": { fp: "zyly6p", text: "A los creyentes comunes los sobresalta la aritmética" },
  "themes.trinity.sum.tert-praxeas.9.2": { fp: "ikoszz", text: "Inseparables y, aun así, distintos entre sí" },
  "themes.trinity.sum.theophilus-2.15.1": { fp: "d9st6t", text: "Tres días como tipos de Dios, el Verbo y la sabiduría" },
  "themes.wisdom-logos.absence.0": { fp: "1qvyx1f", text: "Nada de lo que hay aquí dice que la Sabiduría o el Verbo se hiciera un ser humano. Ese es el único paso que da Juan 1:14 y que ningún texto judío de esta biblioteca da. Lo más cercano es Baruc 3:37, abajo —«después se mostró en la tierra y convivió con los hombres»—, que los Padres leyeron como la encarnación y que todo lector debería comprobar en su contexto: las líneas siguientes identifican lo que apareció con el libro de los mandamientos. Baruc hace lo mismo que Sirácida 24: dice que la Sabiduría bajó como la Ley." },
  "themes.wisdom-logos.absence.1": { fp: "t51plh", text: "El Targum Neofiti no está en esta biblioteca, y es el texto que más se cita en esta discusión: su Génesis 1:1 dice «En el principio y con gran sabiduría, Dios creó y acabó los cielos y la tierra», lo más cerca de Juan 1:1 que llega una frase judía, y la razón por la que se recurre a él. De Neofiti solo existen ocho versículos en alguna versión inglesa con licencia abierta (ese entre ellos, en la traducción comunitaria CC0 de Sefaria); el resto, y todo Onkelos, están disponibles únicamente bajo licencias que esta aplicación no puede usar. Así que lo que hay aquí es Pseudo-Jonatán e Isaías: suficiente para mostrar el hábito del Memrá, pero no el versículo que todo el mundo cita." },
  "themes.wisdom-logos.anchors": { fp: "1q2elhc", text: "Las anclas son Proverbios 8:22–31 (la Sabiduría poseída al principio de su camino, junto a él como artífice), Job 28, Salmo 33:6 y Génesis 1:3. Son canónicos y quedan fuera de este corpus; Sirácida 24, abajo, está escrito como continuación deliberada de Proverbios 8, y toda esta página es una discusión sobre qué autorizó ese capítulo." },
  "themes.wisdom-logos.blurb": { fp: "733pjj", text: "Cuatro tradiciones, trabajando por separado, llegan cada una a algo que está entre Dios y el mundo. La poesía sapiencial judía hace de la Sabiduría una persona que estaba allí en la creación, y después se divide: el Sirácida la asienta en Jacob y dice sin rodeos que ella es la Torá, mientras que 1 Enoc dice que buscó dónde vivir entre los seres humanos, no halló lugar y se volvió con los ángeles. Filón llama al Logos instrumento de Dios, su imagen, su hijo primogénito, su sumo sacerdote, y dos veces «el segundo dios». Los Targumim ponen la Palabra del Señor donde el hebreo tiene a Dios mismo, en más de cuatrocientos versículos solo de esta biblioteca. Los estoicos dicen que el principio activo en la materia es la razón, y que la razón es Dios. Justino reúne después todos estos títulos en una sola figura y les dice a los griegos que sus filósofos tuvieron parte en ese mismo Logos. Casi todo lo que hay en Juan 1 anda suelto por este material, salvo una cosa, que está en las ausencias, abajo." },
  "themes.wisdom-logos.label": { fp: "gctw57", text: "Sabiduría, Verbo y preexistencia" },
  "themes.wisdom-logos.sum.1enoch.42.2": { fp: "nt6w1o", text: "Sin lugar entre la gente; de vuelta con los ángeles" },
  "themes.wisdom-logos.sum.Bar.3.37": { fp: "14f5ry3", text: "Después apareció en la tierra entre los hombres" },
  "themes.wisdom-logos.sum.Sir.1.4": { fp: "xbu269", text: "La Sabiduría, creada antes que todas las cosas" },
  "themes.wisdom-logos.sum.Sir.24.23": { fp: "kx8lim", text: "Todo esto es la ley que Moisés mandó" },
  "themes.wisdom-logos.sum.Sir.24.3": { fp: "14ztvzu", text: "Salí de la boca del Altísimo" },
  "themes.wisdom-logos.sum.Sir.24.8": { fp: "14lbbda", text: "Se le manda plantar su tienda en Jacob" },
  "themes.wisdom-logos.sum.Wis.7.25": { fp: "1wl0mxe", text: "Aliento del poder de Dios, que mana de su gloria" },
  "themes.wisdom-logos.sum.Wis.7.26": { fp: "we62e3", text: "Resplandor, espejo sin mancha, imagen de la bondad" },
  "themes.wisdom-logos.sum.Wis.9.9": { fp: "1ukr2ng", text: "Presente contigo cuando hiciste el mundo" },
  "themes.wisdom-logos.sum.greco-diogenes-laertius.7.134": { fp: "1264w8p", text: "El principio activo es la razón, y es Dios" },
  "themes.wisdom-logos.sum.justin-1apology.46.1": { fp: "p9tnve", text: "Sócrates y Abraham vivieron conforme al Verbo" },
  "themes.wisdom-logos.sum.justin-2apology.13.1": { fp: "orl2kl", text: "Cada uno habló bien por su parte de la semilla" },
  "themes.wisdom-logos.sum.justin-dialogue.61.1": { fp: "t0fuxt", text: "Gloria, Hijo, Sabiduría, Ángel, Dios, Señor, Logos" },
  "themes.wisdom-logos.sum.philo-alleg-interp.3.96": { fp: "f3dev6", text: "El Verbo: instrumento de Dios al hacer el mundo" },
  "themes.wisdom-logos.sum.philo-dreams.1.215": { fp: "16t4liz", text: "Sumo sacerdote del mundo, su hijo primogénito" },
  "themes.wisdom-logos.sum.philo-flight.1.101": { fp: "1o07ioa", text: "Imagen de Dios, el más cercano a él, auriga de las potencias" },
  "themes.wisdom-logos.sum.philo-qg.2.62": { fp: "1bf2rq0", text: "Hecho conforme a la segunda deidad, el Verbo de Dios" },
  "themes.wisdom-logos.sum.tg-isaiah.12.2": { fp: "12vbt0p", text: "Por su Palabra ha llegado a ser mi salvación" },
  "themes.wisdom-logos.sum.tg-psj-deuteronomy.4.7": { fp: "huvbvl", text: "La Palabra entronizada, y que oye nuestra oración" },
  "themes.wisdom-logos.sum.tg-psj-genesis.3.8": { fp: "lo3pf7", text: "La Palabra del Señor paseando por el huerto" },
}
